//! Schema descriptors generated by `build/` and schema-driven walks over encoded bytes.
//!
//! The walks are deliberately independent of both codecs under test: they convert encoded
//! messages to JSON for the bare-ts corpus, find maps with several pairs, and rewrite the
//! reference implementation's output where it diverges from the BARE specification.

use serde_json::{json, Value};

/// One BARE type. Named types are references to other descriptors.
#[derive(Debug)]
pub enum Desc {
    Uint,
    Int,
    U8,
    U16,
    U32,
    U64,
    I8,
    I16,
    I32,
    I64,
    F32,
    F64,
    Bool,
    Str,
    Data,
    FixedData(usize),
    Void,
    Optional(&'static Desc),
    List(&'static Desc),
    FixedList(&'static Desc, usize),
    Map(&'static Desc, &'static Desc),
    /// Value names and their declared values, in declaration order.
    Enum(&'static [(&'static str, u64)]),
    /// Member tags and types.
    Union(&'static [(u64, &'static Desc)]),
    /// Field names as written in the schema, and their types.
    Struct(&'static [(&'static str, &'static Desc)]),
}

/// `bare_proc` 0.2.0 represents `data[N]` and `list<T>[N]` as Rust arrays only up to this length.
pub const REFERENCE_ARRAY_LIMIT: usize = 32;

impl Desc {
    /// Whether `bare_proc` 0.2.0 with `serde_bare` 0.5.0 encodes some value of this type
    /// differently from the BARE specification (see [`reference_to_spec`]).
    pub fn has_reference_bug(&self) -> bool {
        match self {
            Desc::Enum(values) => values
                .iter()
                .enumerate()
                .any(|(index, (_, value))| *value != index as u64),
            Desc::FixedData(length) => *length > REFERENCE_ARRAY_LIMIT,
            Desc::FixedList(inner, length) => {
                *length > REFERENCE_ARRAY_LIMIT || inner.has_reference_bug()
            }
            Desc::Optional(inner) | Desc::List(inner) => inner.has_reference_bug(),
            Desc::Map(key, value) => key.has_reference_bug() || value.has_reference_bug(),
            Desc::Union(members) => members.iter().any(|(_, member)| member.has_reference_bug()),
            Desc::Struct(fields) => fields.iter().any(|(_, field)| field.has_reference_bug()),
            Desc::Uint
            | Desc::Int
            | Desc::U8
            | Desc::U16
            | Desc::U32
            | Desc::U64
            | Desc::I8
            | Desc::I16
            | Desc::I32
            | Desc::I64
            | Desc::F32
            | Desc::F64
            | Desc::Bool
            | Desc::Str
            | Desc::Data
            | Desc::Void => false,
        }
    }
}

/// A cursor over bytes being walked. Errors are strings because the walks only run in tests.
struct Cursor<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Cursor<'a> {
    fn take(&mut self, len: usize) -> Result<&'a [u8], String> {
        let end = self
            .pos
            .checked_add(len)
            .filter(|end| *end <= self.bytes.len())
            .ok_or_else(|| format!("truncated at byte {}", self.pos))?;
        let out = &self.bytes[self.pos..end];
        self.pos = end;
        Ok(out)
    }

    fn uint(&mut self) -> Result<u64, String> {
        let (value, len) = vbare::varint::read_uint_lenient(&self.bytes[self.pos..]);
        if len == 0 || self.bytes[self.pos + len - 1] & 0x80 != 0 {
            return Err(format!("truncated varint at byte {}", self.pos));
        }
        self.pos += len;
        Ok(value)
    }

    fn array<const N: usize>(&mut self) -> Result<[u8; N], String> {
        let mut out = [0u8; N];
        out.copy_from_slice(self.take(N)?);
        Ok(out)
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

/// Decodes `bytes`, which must hold exactly one valid value, into the corpus JSON format shared
/// with `bare-ts/check.mjs`:
///
/// - `u64`, `i64`, `uint` and `int` as decimal strings; smaller integers as numbers;
/// - floats as lowercase hex bit patterns (8 or 16 digits);
/// - `data` and `data[N]` as lowercase hex;
/// - enums as their declared numeric value;
/// - unions as `{"tag": n, "value": v}`, with `null` for void members;
/// - optionals as `null` or the value;
/// - maps as `[key, value]` pairs in encoded order;
/// - structs as objects keyed by schema field names.
///
/// Signaling `f32` NaNs and present optionals holding `null` are reported as errors, because
/// JavaScript cannot represent them.
pub fn to_json(desc: &Desc, bytes: &[u8]) -> Result<Value, String> {
    let mut cursor = Cursor { bytes, pos: 0 };
    let value = json_value(desc, &mut cursor)?;
    if cursor.pos != bytes.len() {
        return Err("trailing bytes".into());
    }
    Ok(value)
}

fn json_value(desc: &Desc, c: &mut Cursor<'_>) -> Result<Value, String> {
    Ok(match desc {
        Desc::Uint => json!(c.uint()?.to_string()),
        Desc::Int => json!(vbare::varint::unzigzag(c.uint()?).to_string()),
        Desc::U8 => json!(c.array::<1>()?[0]),
        Desc::U16 => json!(u16::from_le_bytes(c.array()?)),
        Desc::U32 => json!(u32::from_le_bytes(c.array()?)),
        Desc::U64 => json!(u64::from_le_bytes(c.array()?).to_string()),
        Desc::I8 => json!(i8::from_le_bytes(c.array()?)),
        Desc::I16 => json!(i16::from_le_bytes(c.array()?)),
        Desc::I32 => json!(i32::from_le_bytes(c.array()?)),
        Desc::I64 => json!(i64::from_le_bytes(c.array()?).to_string()),
        Desc::F32 => {
            let bits = u32::from_le_bytes(c.array()?);
            let signaling = bits & 0x7f80_0000 == 0x7f80_0000
                && bits & 0x007f_ffff != 0
                && bits & 0x0040_0000 == 0;
            if signaling {
                return Err("signaling f32 NaN".into());
            }
            json!(format!("{bits:08x}"))
        }
        Desc::F64 => json!(format!("{:016x}", u64::from_le_bytes(c.array()?))),
        Desc::Bool => json!(c.array::<1>()?[0] == 1),
        Desc::Str => {
            let len = c.uint()? as usize;
            let bytes = c.take(len)?;
            json!(std::str::from_utf8(bytes).map_err(|error| error.to_string())?)
        }
        Desc::Data => {
            let len = c.uint()? as usize;
            json!(hex(c.take(len)?))
        }
        Desc::FixedData(length) => json!(hex(c.take(*length)?)),
        Desc::Void => Value::Null,
        Desc::Optional(inner) => match c.array::<1>()?[0] {
            0 => Value::Null,
            _ => {
                // `optional<optional<T>>` holding an empty inner optional has no JSON (or
                // bare-ts) representation distinct from the empty outer optional.
                let value = json_value(inner, c)?;
                if value.is_null() {
                    return Err("present optional holding null".into());
                }
                value
            }
        },
        Desc::List(inner) => {
            let count = c.uint()?;
            let mut items = Vec::new();
            for _ in 0..count {
                items.push(json_value(inner, c)?);
            }
            Value::Array(items)
        }
        Desc::FixedList(inner, length) => {
            let mut items = Vec::new();
            for _ in 0..*length {
                items.push(json_value(inner, c)?);
            }
            Value::Array(items)
        }
        Desc::Map(key, value) => {
            let count = c.uint()?;
            let mut pairs = Vec::new();
            for _ in 0..count {
                let key = json_value(key, c)?;
                let value = json_value(value, c)?;
                pairs.push(json!([key, value]));
            }
            Value::Array(pairs)
        }
        Desc::Enum(_) => json!(c.uint()?),
        Desc::Union(members) => {
            let tag = c.uint()?;
            let member = members
                .iter()
                .find(|(candidate, _)| *candidate == tag)
                .ok_or_else(|| format!("unknown union tag {tag}"))?;
            json!({ "tag": tag, "value": json_value(member.1, c)? })
        }
        Desc::Struct(fields) => {
            let mut object = serde_json::Map::new();
            for (name, field) in fields.iter() {
                object.insert((*name).to_owned(), json_value(field, c)?);
            }
            Value::Object(object)
        }
    })
}

/// The largest number of pairs in any map inside the valid message `bytes`.
pub fn max_map_len(desc: &Desc, bytes: &[u8]) -> Result<u64, String> {
    let mut cursor = Cursor { bytes, pos: 0 };
    let mut max = 0;
    walk_maps(desc, &mut cursor, &mut max)?;
    Ok(max)
}

fn walk_maps(desc: &Desc, c: &mut Cursor<'_>, max: &mut u64) -> Result<(), String> {
    match desc {
        Desc::Uint | Desc::Int | Desc::Enum(_) => {
            c.uint()?;
        }
        Desc::U8 | Desc::I8 | Desc::Bool => {
            c.take(1)?;
        }
        Desc::U16 | Desc::I16 => {
            c.take(2)?;
        }
        Desc::U32 | Desc::I32 | Desc::F32 => {
            c.take(4)?;
        }
        Desc::U64 | Desc::I64 | Desc::F64 => {
            c.take(8)?;
        }
        Desc::Str | Desc::Data => {
            let len = c.uint()? as usize;
            c.take(len)?;
        }
        Desc::FixedData(length) => {
            c.take(*length)?;
        }
        Desc::Void => {}
        Desc::Optional(inner) => {
            if c.array::<1>()?[0] != 0 {
                walk_maps(inner, c, max)?;
            }
        }
        Desc::List(inner) => {
            for _ in 0..c.uint()? {
                walk_maps(inner, c, max)?;
            }
        }
        Desc::FixedList(inner, length) => {
            for _ in 0..*length {
                walk_maps(inner, c, max)?;
            }
        }
        Desc::Map(key, value) => {
            let count = c.uint()?;
            *max = (*max).max(count);
            for _ in 0..count {
                walk_maps(key, c, max)?;
                walk_maps(value, c, max)?;
            }
        }
        Desc::Union(members) => {
            let tag = c.uint()?;
            let member = members
                .iter()
                .find(|(candidate, _)| *candidate == tag)
                .ok_or_else(|| format!("unknown union tag {tag}"))?;
            walk_maps(member.1, c, max)?;
        }
        Desc::Struct(fields) => {
            for (_, field) in fields.iter() {
                walk_maps(field, c, max)?;
            }
        }
    }
    Ok(())
}

/// Rewrites bytes produced by the reference implementation (`bare_proc` 0.2.0 generating types
/// for `serde_bare` 0.5.0, both from crates.io) into the encoding draft-devault-bare-11 requires.
///
/// The reference violates the specification in exactly three ways, all present in
/// `bare_proc` 0.2.0, in `bare_proc` master `36dcf96` (2024-06-01) and in `vbare` 0.1.0
/// (`6664318`), checked 2026-10-17. Everything else is copied unchanged.
pub fn reference_to_spec(desc: &Desc, bytes: &[u8]) -> Result<Vec<u8>, String> {
    let mut cursor = Cursor { bytes, pos: 0 };
    let mut out = Vec::with_capacity(bytes.len());
    transcode(desc, &mut cursor, &mut out)?;
    if cursor.pos != bytes.len() {
        return Err("trailing bytes in reference output".into());
    }
    Ok(out)
}

fn copy_uint(c: &mut Cursor<'_>, out: &mut Vec<u8>) -> Result<u64, String> {
    let value = c.uint()?;
    vbare::varint::put_uint(out, value);
    Ok(value)
}

fn transcode(desc: &Desc, c: &mut Cursor<'_>, out: &mut Vec<u8>) -> Result<(), String> {
    match desc {
        Desc::Uint | Desc::Int => {
            copy_uint(c, out)?;
        }
        Desc::U8 | Desc::I8 | Desc::Bool => out.extend_from_slice(c.take(1)?),
        Desc::U16 | Desc::I16 => out.extend_from_slice(c.take(2)?),
        Desc::U32 | Desc::I32 | Desc::F32 => out.extend_from_slice(c.take(4)?),
        Desc::U64 | Desc::I64 | Desc::F64 => out.extend_from_slice(c.take(8)?),
        Desc::Str | Desc::Data => {
            let len = copy_uint(c, out)? as usize;
            out.extend_from_slice(c.take(len)?);
        }
        Desc::FixedData(length) => {
            if *length > REFERENCE_ARRAY_LIMIT {
                // Reference bug: `data[N]` with N > 32 becomes `Vec<u8>`, which serde_bare
                // writes with a length prefix. Spec section 2.1 (`data[length]`): "The length
                // (in octets) is not encoded into the message." Strip the prefix.
                let prefix = c.uint()?;
                if prefix != *length as u64 {
                    return Err(format!(
                        "reference wrote data[{length}] with length {prefix}"
                    ));
                }
            }
            out.extend_from_slice(c.take(*length)?);
        }
        Desc::Void => {}
        Desc::Optional(inner) => {
            let tag = c.take(1)?;
            out.extend_from_slice(tag);
            if tag[0] != 0 {
                transcode(inner, c, out)?;
            }
        }
        Desc::List(inner) => {
            for _ in 0..copy_uint(c, out)? {
                transcode(inner, c, out)?;
            }
        }
        Desc::FixedList(inner, length) => {
            if *length > REFERENCE_ARRAY_LIMIT {
                // Reference bug: `list<T>[N]` with N > 32 becomes `Vec<T>`, which serde_bare
                // writes with a count prefix. Spec section 2.2 (`list<type>[length]`): "The
                // length is not encoded into the message." Strip the prefix.
                let prefix = c.uint()?;
                if prefix != *length as u64 {
                    return Err(format!(
                        "reference wrote list[{length}] with count {prefix}"
                    ));
                }
            }
            for _ in 0..*length {
                transcode(inner, c, out)?;
            }
        }
        Desc::Map(key, value) => {
            for _ in 0..copy_uint(c, out)? {
                transcode(key, c, out)?;
                transcode(value, c, out)?;
            }
        }
        Desc::Enum(values) => {
            // Reference bug: serde's `serialize_unit_variant` writes the variant index, so an
            // enum value with an explicit `= N` is encoded as its position. Spec section 3.3:
            // "If a value is explicitly specified, automatic assignment continues from that
            // value plus one." Map the index to the declared value.
            let index = c.uint()?;
            let value = values
                .get(index as usize)
                .ok_or_else(|| format!("reference wrote enum index {index}"))?
                .1;
            vbare::varint::put_uint(out, value);
        }
        Desc::Union(members) => {
            let tag = copy_uint(c, out)?;
            let member = members
                .iter()
                .find(|(candidate, _)| *candidate == tag)
                .ok_or_else(|| format!("unknown union tag {tag}"))?;
            transcode(member.1, c, out)?;
        }
        Desc::Struct(fields) => {
            for (_, field) in fields.iter() {
                transcode(field, c, out)?;
            }
        }
    }
    Ok(())
}
